unsafe fn action(hwnd:HWND,s:&State,a:Action){
 if a==Action::Close{if let(Some(b),Some(r))=(s.backend.borrow_mut().as_mut(),s.runtime.borrow().as_ref()){b.record_close_intent(r);}}

 // Modern modal binding preserves confirmation-before-return/logout ordering.
 // Native modal owner/control rendering remains outside this candidate.
 if a==Action::Close {
  let token={let mut r=s.runtime.borrow_mut();let Some(r)=r.as_mut()else{return;};
   r.java_return_control(super::native_city_runtime::java_return::Intent::Logout).map(|c|r.request_java_return_confirmation(&c)).transpose()};
  let token=match token{Ok(t)=>t,Err(e)=>{show_error(s,&e);return;}};
  let yes=MessageBoxW(Some(hwnd),w!("確定要離開嗎？"),w!("離開"),MB_YESNO|MB_ICONQUESTION|MB_DEFBUTTON2)==IDYES;
  if let Some(b)=s.backend.borrow_mut().as_mut(){b.record_entry_step("close_confirmation",Some(yes));}
  if let Some(confirmation)=token {
   let result=s.runtime.borrow_mut().as_mut().unwrap().handle_player_entry_command(EntryCommand::ConfirmJavaReturn{confirmation:&confirmation,accepted:yes});
   if let Err(e)=result{show_error(s,&e);}else{refresh(hwnd,s);}return;
  }
  if !yes{return;}
 }
 let result={let mut r=s.runtime.borrow_mut();let Some(r)=r.as_mut() else{return;};if a==Action::Close{r.handle_player_entry_command(EntryCommand::Close)}else{r.handle(a)}};
 if let Err(e)=result{show_error(s,&e);}else{refresh(hwnd,s);}
}
